using TrainerSphere.SharedKernel.Results;

namespace TrainerSphere.Api.Modules.Training.Domain;

/// <summary>
/// One logged set. Ids are generated by the client so offline writes can be replayed safely.
/// </summary>
internal sealed record SessionSet(
    Guid Id,
    Guid SessionId,
    Guid ExerciseId,
    int Position,
    int SetNumber,
    decimal? WeightKg,
    int? Reps,
    int? DurationSeconds,
    decimal? DistanceMeters,
    decimal? Rpe,
    bool Completed,
    string? Notes,
    DateTime UpdatedAt)
{
    public const int MaxPosition = 50;
    public const int MaxSetNumber = 50;
    public const decimal MaxWeightKg = 1000m;
    public const int MaxReps = 1000;
    public const int MaxDurationSeconds = 86_400;
    public const decimal MaxDistanceMeters = 1_000_000m;
    public const int NotesMaxLength = 1000;

    /// <summary>
    /// Gets weight x reps for a completed set, zero otherwise (bodyweight sets have no weight).
    /// </summary>
    public decimal Volume => Completed && WeightKg is { } weight && Reps is { } reps ? weight * reps : 0m;
}

internal sealed record SessionTotals(decimal TotalVolumeKg, int CompletedSets, int TotalReps, int? DurationSeconds)
{
    public static SessionTotals Of(IEnumerable<SessionSet> sets, DateTime startedAt, DateTime? completedAt)
    {
        ArgumentNullException.ThrowIfNull(sets);

        SessionSet[] completed = [.. sets.Where(s => s.Completed)];

        return new SessionTotals(
            completed.Sum(s => s.Volume),
            completed.Length,
            completed.Sum(s => s.Reps ?? 0),
            completedAt is { } end ? (int)Math.Max(0, Math.Round((end - startedAt).TotalSeconds)) : null);
    }
}

/// <summary>
/// A client's workout log, either started from an assignment (whose snapshot becomes the prescription) or ad hoc.
/// </summary>
internal sealed class Session
{
    public const int NameMaxLength = 100;
    public const int NotesMaxLength = 2000;

    /// <summary>
    /// Offline clients may send their own clock; tolerate this much skew into the future.
    /// </summary>
    public static readonly TimeSpan AllowedClockSkew = TimeSpan.FromMinutes(5);

    private Session(SessionState state)
    {
        Id = state.Id;
        ClientId = state.ClientId;
        TrainerId = state.TrainerId;
        AssignmentId = state.AssignmentId;
        WorkoutName = state.WorkoutName;
        Status = state.Status;
        StartedAt = state.StartedAt;
        CompletedAt = state.CompletedAt;
        Notes = state.Notes;
        Prescription = state.Prescription;
        CreatedAt = state.CreatedAt;
        UpdatedAt = state.UpdatedAt;
    }

    public Guid Id { get; }

    public Guid ClientId { get; }

    public Guid TrainerId { get; }

    public Guid? AssignmentId { get; }

    public string WorkoutName { get; private set; }

    public SessionStatus Status { get; private set; }

    public DateTime StartedAt { get; }

    public DateTime? CompletedAt { get; private set; }

    public string? Notes { get; private set; }

    public IReadOnlyList<WorkoutExerciseView> Prescription { get; }

    public DateTime CreatedAt { get; }

    public DateTime UpdatedAt { get; private set; }

    public bool IsCompleted => Status == SessionStatus.Completed;

    public static Session Start(Guid id, ClientProfile client, Assignment? assignment, string? workoutName, DateTime startedAt, DateTime now)
    {
        ArgumentNullException.ThrowIfNull(client);

        string name = Text.NullIfBlank(workoutName) ?? assignment?.Workout.Name ?? "Workout";

        return new Session(new SessionState(
            id,
            client.Id,
            client.TrainerId,
            assignment?.Id,
            name,
            SessionStatus.InProgress,
            startedAt,
            CompletedAt: null,
            Notes: null,
            assignment?.Workout.Exercises ?? [],
            now,
            now));
    }

    public static Session Restore(SessionState state)
    {
        ArgumentNullException.ThrowIfNull(state);

        return new Session(state);
    }

    public bool IsAccessibleBy(Viewer viewer) => viewer.IsTrainer ? TrainerId == viewer.UserId : ClientId == viewer.UserId;

    public SessionState ToState() =>
        new(Id, ClientId, TrainerId, AssignmentId, WorkoutName, Status, StartedAt, CompletedAt, Notes, Prescription, CreatedAt, UpdatedAt);

    public void Rename(string workoutName, string? notes, DateTime now)
    {
        WorkoutName = workoutName.Trim();
        Notes = Text.NullIfBlank(notes);
        UpdatedAt = now;
    }

    public Result<Session> EnsureInProgress() => IsCompleted ? SessionErrors.Completed : this;

    /// <summary>
    /// Completes the session. Completing a completed session is a no-op so offline retries are safe; the
    /// returned flag tells whether this call completed it.
    /// </summary>
    public Result<bool> Complete(DateTime completedAt, string? notes, DateTime now)
    {
        if (IsCompleted)
        {
            return false;
        }

        if (completedAt < StartedAt)
        {
            return ValidationError.For("completedAt", "The completion time cannot be before the start time.");
        }

        Status = SessionStatus.Completed;
        CompletedAt = completedAt;
        Notes = Text.NullIfBlank(notes) ?? Notes;
        UpdatedAt = now;
        return true;
    }
}

internal sealed record SessionState(
    Guid Id,
    Guid ClientId,
    Guid TrainerId,
    Guid? AssignmentId,
    string WorkoutName,
    SessionStatus Status,
    DateTime StartedAt,
    DateTime? CompletedAt,
    string? Notes,
    IReadOnlyList<WorkoutExerciseView> Prescription,
    DateTime CreatedAt,
    DateTime UpdatedAt);
